CREATE TYPE "EcommerceOrderStatus" AS ENUM ('PAYMENT_PENDING', 'PAID', 'PROCESSING', 'PACKED', 'SHIPPED', 'DELIVERED', 'CANCELLED', 'RETURN_REQUESTED', 'RETURNED', 'REFUNDED', 'PAYMENT_EXPIRED');
CREATE TABLE "ecommerce_orders" ("id" TEXT NOT NULL,"orderNumber" TEXT NOT NULL,"userId" TEXT NOT NULL,"status" "EcommerceOrderStatus" NOT NULL DEFAULT 'PAYMENT_PENDING',"subtotalAmountPaise" INTEGER NOT NULL,"taxAmountPaise" INTEGER NOT NULL DEFAULT 0,"shippingAmountPaise" INTEGER NOT NULL DEFAULT 0,"totalAmountPaise" INTEGER NOT NULL,"addressSnapshot" JSONB NOT NULL,"reservedUntil" TIMESTAMP(3),"cancellationReason" TEXT,"returnReason" TEXT,"courierName" TEXT,"trackingNumber" TEXT,"trackingUrl" TEXT,"shippedAt" TIMESTAMP(3),"deliveredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ecommerce_orders_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ecommerce_order_items" ("id" TEXT NOT NULL,"orderId" TEXT NOT NULL,"variantId" TEXT NOT NULL,"productSnapshot" JSONB NOT NULL,"unitAmountPaise" INTEGER NOT NULL,"quantity" INTEGER NOT NULL,"totalAmountPaise" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ecommerce_order_items_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ecommerce_orders_orderNumber_key" ON "ecommerce_orders"("orderNumber"); CREATE INDEX "ecommerce_orders_userId_createdAt_idx" ON "ecommerce_orders"("userId", "createdAt"); CREATE INDEX "ecommerce_orders_status_reservedUntil_idx" ON "ecommerce_orders"("status", "reservedUntil"); CREATE INDEX "ecommerce_order_items_orderId_idx" ON "ecommerce_order_items"("orderId");
ALTER TABLE "ecommerce_orders" ADD CONSTRAINT "ecommerce_orders_userId_fkey" FOREIGN KEY ("userId") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ecommerce_order_items" ADD CONSTRAINT "ecommerce_order_items_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "ecommerce_orders"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ecommerce_order_items" ADD CONSTRAINT "ecommerce_order_items_variantId_fkey" FOREIGN KEY ("variantId") REFERENCES "ecommerce_product_variants"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
